#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f (J7 iii, J1 i): own enumeration of every field path of the
version_1, version_2 and version_3 layers of H-NISTBIN-dec5e1 (bytes bound by
TASK-20261002-1d1f48), compared field by field with version_4.supersedes_for_version_4
.in_force_index. Own code; PyYAML compose() only for node marks. Reads only the file
named on the command line. Prints JSON."""
import sys, json, yaml

path = sys.argv[1]
raw = open(path, 'rb').read()
root = yaml.compose(raw.decode('utf-8'))
data = yaml.safe_load(raw)

assert isinstance(root, yaml.MappingNode)
# top mapping is {'hypothesis': {...}}
hyp_node = None
for k, v in root.value:
    if k.value == 'hypothesis':
        hyp_node = v
assert hyp_node is not None

def walk(node, prefix, out):
    """Every mapping key at any depth and every list element, as DI-INDEX defines."""
    if isinstance(node, yaml.MappingNode):
        for k, v in node.value:
            p = k.value if not prefix else prefix + '.' + k.value
            out.append((p, v))
            walk(v, p, out)
    elif isinstance(node, yaml.SequenceNode):
        for i, v in enumerate(node.value):
            p = '%s[%d]' % (prefix, i)
            out.append((p, v))
            walk(v, p, out)

allpaths = []
walk(hyp_node, '', allpaths)

def layer_of(p):
    head = p.split('.')[0].split('[')[0]
    if head == 'version_4':
        return 'version_4'
    if head == 'version_2':
        return 'version_2'
    if head == 'version_3':
        return 'version_3'
    return 'version_1'

earlier = [(p, n) for p, n in allpaths if layer_of(p) != 'version_4']
v4paths = {p for p, n in allpaths if layer_of(p) == 'version_4'}
v4paths_rel = {p[len('version_4.'):] for p in v4paths}
node_of = {p: n for p, n in allpaths}

idx = data['hypothesis']['version_4']['supersedes_for_version_4']['in_force_index']
res = {'n_earlier_paths': len(earlier), 'n_index_entries': len(idx)}
idx_paths = [e['path'] for e in idx]
from collections import Counter
dup = [p for p, c in Counter(idx_paths).items() if c > 1]
res['duplicate_index_paths'] = dup
earlier_set = [p for p, _ in earlier]
missing = [p for p in earlier_set if p not in set(idx_paths)]
extra = [p for p in idx_paths if p not in set(earlier_set)]
res['earlier_paths_missing_from_index'] = missing
res['index_paths_not_existing'] = extra
order_ok = [p for p in idx_paths if p in set(earlier_set)] == [p for p in earlier_set if p in set(idx_paths)]
res['index_order_equals_document_order'] = order_ok

# layer labels and element ids
bad_layer = []
bad_element = []
for e in idx:
    p = e['path']
    if p in node_of:
        if e.get('layer') != layer_of(p):
            bad_layer.append((p, e.get('layer'), layer_of(p)))
        n = node_of[p]
        if 'element' in e:
            # element id: the 'id' key of a mapping element, if present
            eid = None
            if isinstance(n, yaml.MappingNode):
                for k, v in n.value:
                    if k.value == 'id' and isinstance(v, yaml.ScalarNode):
                        eid = v.value
            if eid != e['element']:
                bad_element.append((p, e['element'], eid))
res['bad_layer_labels'] = bad_layer
res['bad_element_labels'] = bad_element
# elements that have an id but carry no element label in the index
missing_element_label = []
for e in idx:
    p = e['path']
    if p in node_of and p.endswith(']') and 'element' not in e:
        n = node_of[p]
        if isinstance(n, yaml.MappingNode):
            for k, v in n.value:
                if k.value == 'id':
                    missing_element_label.append((p, v.value))
res['elements_with_id_but_no_element_label'] = missing_element_label

# status vocabulary and container rule
status = {e['path']: e['status'] for e in idx}
bad_status_vocab = [(p, s) for p, s in status.items() if s not in ('in_force', 'superseded_by_version_4')]
res['bad_status_vocab'] = bad_status_vocab
children = {}
for p, n in earlier:
    children.setdefault(p, [])
for p, n in earlier:
    # parent path
    if p.endswith(']'):
        parent = p[:p.rfind('[')]
    elif '.' in p:
        parent = p[:p.rfind('.')]
    else:
        parent = None
    # careful: a path like a[0].b has parent a[0]
    if parent is not None and parent in children:
        children[parent].append(p)
container_violations = []
for p, kids in children.items():
    if kids and p in status:
        want = 'in_force' if any(status.get(c) == 'in_force' for c in kids) else 'superseded_by_version_4'
        if status[p] != want:
            container_violations.append({'path': p, 'index_status': status[p], 'rule_status': want,
                                         'children_in_force': [c for c in kids if status.get(c) == 'in_force']})
res['container_rule_violations'] = container_violations

# 'by' targets
by_checks = []
for e in idx:
    if e['status'] != 'superseded_by_version_4':
        if 'by' in e:
            by_checks.append({'path': e['path'], 'problem': 'in_force entry carries by', 'by': e['by']})
        continue
    b = e.get('by')
    if b is None:
        by_checks.append({'path': e['path'], 'problem': 'superseded entry without by'})
        continue
    if b.startswith('version_4.'):
        if b not in v4paths:
            by_checks.append({'path': e['path'], 'problem': 'by path does not exist in version_4 block', 'by': b})
    else:
        # an in-force earlier path
        if b not in node_of:
            by_checks.append({'path': e['path'], 'problem': 'by earlier path does not exist', 'by': b})
        elif status.get(b) != 'in_force':
            by_checks.append({'path': e['path'], 'problem': 'by earlier path is not in_force', 'by': b, 'by_status': status.get(b)})
res['by_target_problems'] = by_checks

# entries with keys other than the convention's
allowed_keys = {'path', 'layer', 'status', 'by', 'element', 'time_figure'}
res['entries_with_unknown_keys'] = [e for e in idx if set(e) - allowed_keys]
res['time_figure_entries'] = [{'path': e['path'], 'by': e.get('by'), 'status': e['status']} for e in idx if e.get('time_figure')]
res['time_figure_entries_in_force'] = [e['path'] for e in idx if e.get('time_figure') and e['status'] == 'in_force']

# in-force leaves with their line spans (1-based) for the sweep
inforce_leaves = []
for p, n in earlier:
    if status.get(p) == 'in_force' and isinstance(n, yaml.ScalarNode):
        inforce_leaves.append({'path': p, 'start_line': n.start_mark.line + 1, 'end_line': n.end_mark.line + 1,
                               'text': n.value})
res['in_force_scalar_leaves'] = inforce_leaves
res['n_in_force_entries'] = sum(1 for e in idx if e['status'] == 'in_force')
res['n_superseded_entries'] = sum(1 for e in idx if e['status'] == 'superseded_by_version_4')
# superseded scalar leaves (for the 'restated?' and time-figure checks)
sup_leaves = []
for p, n in earlier:
    if status.get(p) == 'superseded_by_version_4' and isinstance(n, yaml.ScalarNode):
        sup_leaves.append({'path': p, 'start_line': n.start_mark.line + 1, 'end_line': n.end_mark.line + 1,
                           'by': next((e.get('by') for e in idx if e['path'] == p), None),
                           'time_figure_flag': next((bool(e.get('time_figure')) for e in idx if e['path'] == p), False),
                           'text': n.value})
res['superseded_scalar_leaves'] = sup_leaves
print(json.dumps(res, indent=1))

