#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f J1 (i)-(ii): build the in-force text set of EXP-NISTBIN-451dfa
version 4 from the committed bytes (snapshot b188c6a4e5, files extracted by git show of
single paths) and scan it for every numeral, segmented into the units of the review
plan's frozen WITH rule: sentence, list item (innermost YAML sequence element), table
row (outermost YAML flow collection) and printed log line (each line of an embedded
verbatim log).  Own code; PyYAML 6.0.1 compose() is used only for node marks.

Output: units.json (every unit with its numerals and an automatic first-pass label for
each numeral: TIME?, MEM, NEUTRAL; the labels are proposals that the reviewer
adjudicates by hand, see adjudication.json).
"""
import json
import re
import sys
import yaml

BYTES = sys.argv[1]
OUT = sys.argv[2]
FILES = {
    'spec': 'experiments/EXP-NISTBIN-451dfa/specification.yaml',
    'hyp': 'ledger/hypotheses/H-NISTBIN-dec5e1.yaml',
    'audit': 'coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/proof-search-map-audit.yaml',
    'worksheet': 'coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/revision-worksheet.yaml',
}
LOCAL = {'spec': 'spec_v4.yaml', 'hyp': 'hyp_v4.yaml', 'audit': 'audit_v4.yaml', 'worksheet': 'worksheet_v4.yaml'}

# ----------------------------------------------------------------------------- numerals
NUM_RE = re.compile(
    r"(?P<pow>2\^\(?-?\d+(?:\.\d+)?\)?)"                 # 2^x or 2^(x)
    r"|(?P<sci>(?<![\w.])[-+]?\d+(?:\.\d+)?e[-+]?\d+)"     # scientific
    r"|(?P<dec>(?<![\w.^/])[-+]?\d+\.\d+(?![\w.]*\d))"     # decimal
    r"|(?P<int>(?<![\w.^/\-])[-+]?\d+(?![\w.]))"           # integer
)
ABBREV = ('eq', 'e.g', 'i.e', 'cf', 'Sec', 'al', 'vs', 'etc', 'Fig', 'No', 'approx', 'resp', 'p')


def line_of(text_index, line_starts):
    lo, hi = 0, len(line_starts) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if line_starts[mid] <= text_index:
            lo = mid
        else:
            hi = mid - 1
    return lo + 1


def sentence_spans(s):
    """Split raw scalar text s into sentence spans (start, end).  A boundary is a '.'
    followed by whitespace and then an upper-case letter, a digit, '(' or a quote,
    unless the token before the '.' is a listed abbreviation or the '.' sits inside a
    decimal number."""
    spans = []
    start = 0
    for mt in re.finditer(r"\.(?=\s+[A-Z0-9(\"'])", s):
        i = mt.start()
        j = i - 1
        while j >= 0 and (s[j].isalnum() or s[j] in '._'):
            j -= 1
        tok = s[j + 1:i]
        if tok in ABBREV or tok.rstrip('.') in ABBREV:
            continue
        spans.append((start, i + 1))
        start = i + 1
    spans.append((start, len(s)))
    return [(a, b) for a, b in spans if s[a:b].strip()]


def compose_nodes(text):
    root = yaml.compose(text)
    out = []  # (path, node, innermost_seq_item(path,node) or None, outermost_flow(path,node) or None)

    def walk(node, path, seq_item, flow):
        f = flow
        if isinstance(node, (yaml.MappingNode, yaml.SequenceNode)) and node.flow_style and flow is None:
            f = (path, node)
        if isinstance(node, yaml.ScalarNode):
            out.append((path, node, seq_item, f))
        elif isinstance(node, yaml.MappingNode):
            for k, v in node.value:
                walk(v, path + ('.' if path else '') + k.value, seq_item, f)
        elif isinstance(node, yaml.SequenceNode):
            for i, v in enumerate(node.value):
                p = '%s[%d]' % (path, i)
                walk(v, p, (p, v), f)
    walk(root, '', None, None)
    return root, out


def classify_prose(s, a, b, kind):
    """First-pass label of a numeral at s[a:b]: MEM, TIME? or NEUTRAL, from a local
    window.  Proposals only."""
    tok = s[a:b]
    before = s[max(0, a - 90):a]
    after = s[b:b + 60]
    bl = before.lower()
    al = after.lower()
    tl = re.sub(r'\s+', ' ', bl)
    al1 = re.sub(r'\s+', ' ', al)
    mem_before = re.search(r"(rows?|macaulay rows|relation store|store|dense entries|entries|memory|mr_b|mr_m|mr_c8|mr_mac|mr_f4|width|w\(n5, ?4\)|distinguished points|storage)[^.;,]{0,40}$", tl)
    mem_after = re.match(r"\s*(\(?(r-b|r-m|c8) form|bits? of (macaulay )?rows|bits? of relation store|bits? of rows|rows|relation|distinguished|gb|= w\(|\(w\(|dense)", al1)
    time_after = re.match(r"\s*(bits?\b(?! of (macaulay )?rows)(?! of relation)|iterations|operations|\(k-571\)|\(b-571\))", al1)
    time_before = re.search(r"(log2 cost|log2_cost|c_i\b|cost|margin|time|stage-1|stage 1|-log2 p|a\(571|lower by|higher by|moves? (it |the cost |the d = 4 time |c_i )?(by|from)|costs|slack|gap|figure|target|to|against|is|becomes|from|at most|about|of|than)\s*[(\[]?\s*$", tl)
    if tok.startswith('2^'):
        if mem_before or mem_after:
            return 'MEM'
        if re.match(r"\s*(iterations|operations|group operations)", al1):
            return 'TIME?'
        return 'MEM?2pow'
    if mem_after or (mem_before and not time_after):
        return 'MEM'
    if time_after:
        return 'TIME?'
    if '.' in tok and time_before:
        return 'TIME?'
    if '.' in tok or 'e' in tok:
        return 'DEC?'
    return 'NEUTRAL'


TIME_KEYS = {'C_I', 'stage1', 'carried_time_log2', 'time_move', 'block_n4w_C_I', 'time_bits',
             'neg_log2_P_PF2', 'log2_m_factorial', 'margin_K_571', 'margin_B_571', 'runner_up_gap',
             'move_ceiled_minus_MI1', 'A_MI1_PF2', 'A_ceiled_PF2', 'A_MI1_PF1', 'A_ceiled_PF1',
             'ceiled_minus_MI1_PF2', 'ceiled_minus_MI1_PF1', 'PF2_minus_PF1_MI1', 'PF2_minus_PF1_ceiled',
             'largest_drop', 'smallest_drop', 'largest', 'smallest', 'move_PF1_minus_PF2',
             'abs_distance', 'slack', 'target', 'margin', 'log2_cost'}
RHO_KEYS = {'rho', 'carried_rho', 'rho_minus_carried'}
MEM_KEYS_RE = re.compile(r'^(MR_|dense_|relation_store|store_|rows_|block_n4w_MR_|block_n4w_relation_store|log2_binom|four_log2_576|MR_B_at|MR_M_at)')
DELTA_KEYS = {'DELTA7', 'DELTA7_max'}


def json_leaf_items(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from json_leaf_items(v, k)
    elif isinstance(obj, list):
        for v in obj:
            yield from json_leaf_items(v, prefix)
    else:
        yield prefix, obj


def classify_log_line(text):
    """For a printed log line: if it carries a JSON object or key: value, classify its
    numeric leaves by key.  Otherwise use prose rules on the line."""
    t = text.strip().rstrip(',')
    obj = None
    for cand in (t, '{' + t + '}'):
        try:
            obj = json.loads(cand)
            break
        except Exception:
            pass
    if obj is None:
        return None
    labs = []
    for k, v in json_leaf_items(obj):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            continue
        if k in TIME_KEYS:
            labs.append((k, v, 'TIME'))
        elif k in RHO_KEYS:
            labs.append((k, v, 'RHO'))
        elif MEM_KEYS_RE.match(k):
            labs.append((k, v, 'MEM'))
        elif k in DELTA_KEYS:
            labs.append((k, v, 'DELTA7'))
        else:
            labs.append((k, v, 'NEUTRAL'))
    return labs


def main():
    di = json.load(open(BYTES + '/../out_di_index.json'))
    hyp_in_force = {e['path'] for e in di['in_force_scalar_leaves']}
    units = []
    numerals = []
    uid = 0
    for key, local in LOCAL.items():
        text = open(BYTES + '/' + local, encoding='utf-8').read()
        line_starts = [0] + [i + 1 for i, ch in enumerate(text) if ch == '\n']
        raw_lines = text.split('\n')
        root, nodes = compose_nodes(text)
        # comments (outside scalars) in spec, audit, worksheet: whole-line comments
        if key != 'hyp':
            for ln, rl in enumerate(raw_lines, 1):
                st = rl.strip()
                if st.startswith('#') and re.search(r'\d', st):
                    uid += 1
                    units.append({'uid': uid, 'file': key, 'kind': 'COMMENT', 'path': '(comment)',
                                  'lines': [ln, ln], 'text': st})
                    for mt in NUM_RE.finditer(st):
                        numerals.append({'uid': uid, 'file': key, 'line': ln, 'tok': mt.group(0),
                                         'label': classify_prose(st, mt.start(), mt.end(), 'COMMENT'),
                                         'ctx': st[max(0, mt.start() - 80):mt.end() + 50]})
        flow_units = {}
        for path, node, seq_item, flow in nodes:
            hpath = path
            if key == 'hyp':
                assert path.startswith('hypothesis')
                hpath = path[len('hypothesis.'):] if path != 'hypothesis' else ''
                if not hpath.startswith('version_4') and hpath not in hyp_in_force:
                    continue
            a, b = node.start_mark.index, node.end_mark.index
            s = text[a:b]
            if not re.search(r'\d', s):
                continue
            seq_path = None
            seq_text = None
            if seq_item is not None:
                sp, sn = seq_item
                seq_path = sp
                seq_text = text[sn.start_mark.index:sn.end_mark.index]
            if flow is not None:
                fp, fn = flow
                fkey = (fp, fn.start_mark.index)
                if fkey in flow_units:
                    continue  # the whole flow collection is one row, done once
                fa, fb = fn.start_mark.index, fn.end_mark.index
                ftext = text[fa:fb]
                uid += 1
                flow_units[fkey] = uid
                u = {'uid': uid, 'file': key, 'kind': 'ROW', 'path': fp,
                     'lines': [line_of(fa, line_starts), line_of(max(fa, fb - 1), line_starts)],
                     'text': ftext, 'list_item': seq_path if seq_path != fp else None}
                units.append(u)
                for mt in NUM_RE.finditer(ftext):
                    numerals.append({'uid': uid, 'file': key, 'line': line_of(fa + mt.start(), line_starts),
                                     'tok': mt.group(0),
                                     'label': classify_prose(ftext, mt.start(), mt.end(), 'ROW'),
                                     'ctx': re.sub(r'\s+', ' ', ftext[max(0, mt.start() - 90):mt.end() + 60])})
                continue
            is_code = key == 'audit' and ('.code_blocks.' in path and path.endswith('.source'))
            is_cmd = key == 'audit' and path.endswith('.commands')
            is_log = key == 'audit' and '.relay.part_' in path
            if node.style == '|' and (is_code or is_cmd or is_log):
                kind = 'CODE' if is_code else ('COMMAND' if is_cmd else 'LOG')
                first = line_of(a, line_starts)
                last = line_of(max(a, b - 1), line_starts)
                for ln in range(first + 1, last + 1):
                    rl = raw_lines[ln - 1]
                    if not re.search(r'\d', rl):
                        continue
                    uid += 1
                    u = {'uid': uid, 'file': key, 'kind': kind, 'path': path, 'lines': [ln, ln], 'text': rl}
                    labs = classify_log_line(rl) if kind == 'LOG' else None
                    if labs is not None:
                        u['json_labels'] = [[k, v, lab] for k, v, lab in labs]
                    units.append(u)
                    if labs is None:
                        for mt in NUM_RE.finditer(rl):
                            numerals.append({'uid': uid, 'file': key, 'line': ln, 'tok': mt.group(0),
                                             'label': ('CODE' if kind == 'CODE' else
                                                       ('COMMAND' if kind == 'COMMAND' else
                                                        classify_prose(rl, mt.start(), mt.end(), 'LOG'))),
                                             'ctx': rl.strip()[:220]})
                    else:
                        for k, v, lab in labs:
                            numerals.append({'uid': uid, 'file': key, 'line': ln, 'tok': '%s=%r' % (k, v),
                                             'label': 'J-' + lab, 'ctx': ''})
                continue
            # prose scalar: sentence units
            for sa, sb in sentence_spans(s):
                sent = s[sa:sb]
                if not re.search(r'\d', sent):
                    continue
                uid += 1
                u = {'uid': uid, 'file': key, 'kind': 'SENT', 'path': hpath if key == 'hyp' else path,
                     'lines': [line_of(a + sa, line_starts), line_of(max(a + sa, a + sb - 1), line_starts)],
                     'text': re.sub(r'\s+', ' ', sent).strip(),
                     'list_item': seq_path, 'list_item_text': (re.sub(r'\s+', ' ', seq_text) if seq_text else None)}
                units.append(u)
                for mt in NUM_RE.finditer(sent):
                    numerals.append({'uid': uid, 'file': key, 'line': line_of(a + sa + mt.start(), line_starts),
                                     'tok': mt.group(0),
                                     'label': classify_prose(sent, mt.start(), mt.end(), 'SENT'),
                                     'ctx': re.sub(r'\s+', ' ', sent[max(0, mt.start() - 90):mt.end() + 60])})
    json.dump({'files': FILES, 'units': units, 'numerals': numerals}, open(OUT, 'w'), indent=0)
    from collections import Counter
    print('units', len(units), Counter(u['kind'] for u in units))
    print('numerals', len(numerals), Counter(n['label'] for n in numerals))


if __name__ == '__main__':
    main()

