#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f J1 (ii): first-pass WITH/WITHOUT evaluation over units.json.
A candidate time figure is WITH-S if a memory figure stands in the same unit (sentence,
table row or printed log line), WITH-L if only in the same innermost list item, else
WITHOUT.  Labels are proposals; the reviewer adjudicates every candidate by hand."""
import json
import re
import sys
sys.path.insert(0, sys.argv[1])
from sweep import NUM_RE, classify_prose  # own module

U = json.load(open(sys.argv[2]))
units = {u['uid']: u for u in U['units']}
by_unit = {}
for n in U['numerals']:
    by_unit.setdefault(n['uid'], []).append(n)


def unit_has_mem(u):
    for n in by_unit.get(u['uid'], []):
        if n['label'] in ('MEM', 'J-MEM'):
            return True
    return False


def text_has_mem(t):
    if not t:
        return False
    for mt in NUM_RE.finditer(t):
        if classify_prose(t, mt.start(), mt.end(), 'X') == 'MEM':
            return True
    return False


cands = []
for n in U['numerals']:
    if n['label'] not in ('TIME?', 'DEC?', 'MEM?2pow', 'J-TIME', 'J-RHO', 'J-DELTA7'):
        continue
    u = units[n['uid']]
    if unit_has_mem(u):
        w = 'WITH-S'
    elif u.get('list_item_text') and text_has_mem(u['list_item_text']):
        w = 'WITH-L'
    else:
        w = 'WITHOUT'
    cands.append(dict(n, kind=u['kind'], path=u['path'], with_=w, unit_text=u['text'][:600]))
json.dump(cands, open(sys.argv[3], 'w'), indent=0)
from collections import Counter
print(Counter((c['label'], c['with_']) for c in cands))

