#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f J1 (ii): final adjudication of every candidate numeral of the
in-force text (units.json from sweep.py) into a class, by explicit rules listed in
RULES below (reviewer's adjudication, stated in advance of the WITH evaluation), and the
WITH evaluation of every time figure under the plan's frozen rule:
  WITH-S  a memory figure for the same object stands in the same sentence, table row or
          printed log line;
  WITH-L  only in the same innermost list item (YAML sequence element);
  WITHOUT otherwise.
Classes: TIME-IC (a time figure of the index-calculus cost model: cost, component,
margin, move or difference between readings, k readings or P forms, slack, gap, per-step
cost, carried or quoted); and the classes the C8-IC reading does not count but the
literal-sensitivity reading does: RHO (rho-side time figure or rho difference), BUDGET
(run wall-clock or CPU budget), PROC (process timing printed in a log).  Not time
figures under either reading: MEM, DELTA7 (memory-side), TOL (tolerance or threshold
of acceptance), RATIO, PARAM, CONST, NEUTRAL, ID, CODE, COMMAND.
argv: <units.json> <prose memory points json> <out json>"""
import json
import re
import sys

U = json.load(open(sys.argv[1]))
P = json.load(open(sys.argv[2]))
OUT = sys.argv[3]
units = {u['uid']: u for u in U['units']}

ID_RE = re.compile(r'^(\d*e\d+|09e2|7e76|8e9|2e63|361e02|649e25|74e208|992e73)$')
OMEGA = {'2.0', '2.376', '2.807', '3.0', '2.37', '2.978'}
NEUTRAL_TOK = {'4.3', '3.12', '78.00', '88.00', '352.75', '352.7520725', '358.00', '6.0.1', '3.11.15'}
CONST = {'0.5', '0.886', '1.069993', '0.1742519', '1.684211', '128.0000'}
RATIO = {'27.2', '14.3', '104.7', '9.5', '276'}
RHO_VALUES = {'38.8257', '43.8257', '176.2018', '174.5818', '279.7471', '284.8257', '136.2534', '140.8257',
              '60.8090', '118.3257', '114.3753', '2^60.8090', '2^60.9', '141.5'}
TOLS = {'5.0e-4', '1e-9', '1e-6', '1e-4', '0.05'}


def strip(t):
    return t.lstrip('+').rstrip(')')


def classify(n, u):
    tok = n['tok']
    t = strip(tok)
    ctx = n['ctx']
    lab = n['label']
    if u['kind'] in ('CODE', 'COMMAND'):
        return u['kind']
    if lab.startswith('J-'):
        k = lab[2:]
        return {'TIME': 'TIME-IC', 'RHO': 'RHO', 'MEM': 'MEM', 'DELTA7': 'DELTA7', 'NEUTRAL': 'NEUTRAL'}[k]
    if u['kind'] == 'LOG':
        if re.match(r'^\s*(real|user|sys)\t', u['text']):
            return 'PROC'
        return 'NEUTRAL'
    if ID_RE.match(t):
        return 'ID'
    if t in OMEGA:
        return 'PARAM'
    if t in NEUTRAL_TOK:
        return 'NEUTRAL'
    if t in CONST:
        if t == '0.5' and re.search(r'0\.5 bit off', ctx):
            return 'RHO'
        return 'CONST'
    if t in RATIO:
        return 'RATIO'
    if t in TOLS:
        return 'TOL'
    if t == '0.01':
        if re.search(r'gap falling below 0\.01 bit', ctx):
            return 'TIME-IC'
        return 'TOL'
    if t == '2' and 'within 2 bits of zero' in ctx:
        return 'TOL'
    if t in ('0.67', '5.5') and 'rho' in ctx.lower():
        return 'RHO'
    if t in RHO_VALUES or (t.startswith('2^60') and 'iteration' in ctx):
        return 'RHO'
    if t in ('285.5', '2^285.5'):
        if re.search(r'relation store 2\^285\.5|store_MI1_at_smallest|store_there', ctx):
            return 'MEM'
        return 'RHO'
    if lab in ('MEM', 'MEM?2pow'):
        m = re.match(r'2\^\(?(-?\d+(?:\.\d+)?)', tok)
        if m and m.group(1) in P:
            return 'MEM'
        if tok in ('2^99',):
            return 'TIME-IC'
        if tok == '2^-90':
            return 'TIME-IC'
        if m:
            return 'NEUTRAL'
        if lab == 'MEM' and ('.' in t or 'e-' in t) and t not in P:
            # reviewer rule: a first-pass MEM label on a bare decimal that is not an
            # adjudicated memory value is a time figure (the label came from a nearby word)
            return 'TIME-IC'
        return 'MEM' if lab == 'MEM' else 'NEUTRAL'
    if lab in ('TIME?', 'DEC?'):
        # memory-valued bare decimals (the rt4 memory_beside lists, PF register rows, 'x bits of rows')
        if t in P and re.search(r'rows|store|memory|entries|binom|dense', ctx):
            after = ctx[ctx.find(tok) + len(tok):][:30]
            if not re.match(r'\s*bits?\b(?! of (Macaulay )?rows)(?! of relation)', after) or re.search(r'bits of (Macaulay )?rows|bits of relation|bits of store', ctx[ctx.find(tok):ctx.find(tok) + 40]):
                return 'MEM'
        return 'TIME-IC'
    if lab == 'MEM':
        # the first-pass MEM label on a bare decimal that is not an adjudicated memory value:
        # reviewer rule -- a decimal not in the memory map is a time figure unless it is a
        # parameter (omega) or an integer label
        if ('.' in t or 'e-' in t) and t not in P:
            return 'TIME-IC'
        return 'MEM'
    return 'NEUTRAL'


MEMKEY = re.compile(r'2\^\(?(-?\d+(?:\.\d+)?)')


def genuine_memory(text, rho=False):
    """Memory witnesses in a text: a 2^x value adjudicated as memory, an 'x bits of rows'
    or 'x bits of relation store' change, 'x rows', or (for rho) a distinguished-point or
    GB storage figure."""
    w = [m.group(0) for m in MEMKEY.finditer(text) if m.group(1) in P]
    w += [m.group(0) for m in re.finditer(r'[-+]?\d+\.\d+ bits of (?:Macaulay )?rows|[-+]?\d+\.\d+ bits of (?:relation )?store|\d+\.\d+ rows', text)]
    if rho:
        w += [m.group(0) for m in re.finditer(r'2\^35\.63 distinguished points|850 GB', text)]
    return w


rows = []
for n in U['numerals']:
    u = units[n['uid']]
    c = classify(n, u)
    rec = {'file': n['file'], 'line': n['line'], 'tok': n['tok'], 'class': c, 'unit': u['kind'], 'path': u['path']}
    if c in ('TIME-IC', 'RHO', 'BUDGET', 'PROC'):
        if u['kind'] == 'LOG':
            labs = u.get('json_labels', [])
            mem = [k for k, v, l in labs if l == 'MEM']
            rec['with'] = 'WITH-S' if (mem and c == 'TIME-IC') else 'WITHOUT'
            rec['witness'] = mem[:4]
        else:
            w = genuine_memory(u['text'], rho=(c == 'RHO'))
            if w:
                rec['with'], rec['witness'] = 'WITH-S', w[:4]
            else:
                li = u.get('list_item_text') if u['kind'] == 'SENT' else None
                wl = genuine_memory(li, rho=(c == 'RHO')) if li else []
                if wl:
                    rec['with'], rec['witness'] = 'WITH-L', wl[:4]
                else:
                    rec['with'], rec['witness'] = 'WITHOUT', []
        rec['ctx'] = (u['text'] if u['kind'] == 'LOG' else n['ctx'])[:240]
    rows.append(rec)

# budget figures are plain scalar fields (wall_clock 900, total_cpu_hours 0.25) found by path
for r in rows:
    if r['path'].endswith('budget.wall_clock_seconds_per_run') or r['path'].endswith('budget.total_cpu_hours'):
        r['class'] = 'BUDGET'
        r['with'] = 'WITHOUT'
        r['witness'] = []
        r['ctx'] = r['path']
    if r['path'].endswith('test_boundary.budget') and r['unit'] == 'ROW' and r['tok'] == '900':
        r['class'] = 'BUDGET'
        r['with'] = 'WITH-S'
        r['witness'] = ['memory_gb: 1']
        r['ctx'] = '{runs: 1, wall_clock_seconds_per_run: 900, memory_gb: 1}'

from collections import Counter
summary = Counter((r['class'], r.get('with')) for r in rows)
json.dump({'rows': rows, 'summary': {'%s|%s' % k: v for k, v in summary.items()}}, open(OUT, 'w'), indent=0)
for k, v in sorted(summary.items(), key=lambda kv: (kv[0][0], str(kv[0][1]))):
    print(k, v)
print('--- TIME-IC WITHOUT:')
for r in rows:
    if r['class'] == 'TIME-IC' and r['with'] == 'WITHOUT':
        print(' ', r['file'], r['line'], r['tok'], r['unit'], r['path'], '|', r['ctx'][:150])

