#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f J7 (iii): for every superseded_by_version_4 entry of in_force_index,
resolve its by path in the committed hypothesis and record whether the target is
non-empty (restates or retires) and, for by paths into version_4, the target's kind.
Own code; PyYAML safe_load.  argv: <hyp file> <out json>"""
import json, re, sys, yaml
from collections import Counter
hyp = yaml.safe_load(open(sys.argv[1], encoding='utf-8'))['hypothesis']
idx = hyp['version_4']['supersedes_for_version_4']['in_force_index']
def resolve(root, path):
    cur = root
    for part in re.findall(r'[^.\[\]]+|\[\d+\]', path):
        if part.startswith('['):
            i = int(part[1:-1])
            if not isinstance(cur, list) or i >= len(cur): return ('__MISSING__',)
            cur = cur[i]
        else:
            if not isinstance(cur, dict) or part not in cur: return ('__MISSING__',)
            cur = cur[part]
    return cur
rows = []
for e in idx:
    if e['status'] != 'superseded_by_version_4':
        continue
    t = resolve(hyp, e['by'])
    missing = isinstance(t, tuple)
    empty = (not missing) and (t is None or t == '' or t == [] or t == {})
    rows.append({'path': e['path'], 'by': e['by'], 'by_resolves': not missing, 'by_target_empty': empty,
                 'by_kind': (None if missing else type(t).__name__), 'into_version_4': e['by'].startswith('version_4.')})
out = {'superseded_entries': len(rows), 'unresolved': [r for r in rows if not r['by_resolves']],
       'empty_targets': [r for r in rows if r['by_target_empty']],
       'by_kinds': Counter(r['by_kind'] for r in rows), 'into_version_4': sum(r['into_version_4'] for r in rows),
       'into_in_force_earlier': sum(not r['into_version_4'] for r in rows), 'rows': rows}
json.dump(out, open(sys.argv[2], 'w'), indent=1)
print({k: (v if not isinstance(v, list) else len(v)) for k, v in out.items() if k != 'rows'})
for r in out['empty_targets']: print('EMPTY', r)
for r in rows:
    if not r['into_version_4']: print('EARLIER', r['path'], '->', r['by'])

