#!/usr/local/bin/python3
"""TASK-20261002-ccdc5f J1 (ii): residual scan for numeral forms the sweep's extractor does
not take as numerals (a digit run glued to letters, e.g. 0m0.076s), over the four
version-4 files; hex digests and ids are skipped.  Own code.  argv: <bytes dir>"""
import re, sys
from collections import Counter
B = sys.argv[1]
c = Counter(); where = {}
for fn in ('spec_v4.yaml', 'hyp_v4.yaml', 'audit_v4.yaml', 'worksheet_v4.yaml'):
    for i, line in enumerate(open(B + '/' + fn, encoding='utf-8'), 1):
        for m in re.finditer(r'(?<![\w.])\d+(?:\.\d+)?[a-zA-Z_][\w.]*', line):
            t = m.group(0)
            if re.fullmatch(r'[0-9a-f]{6,}', t):
                continue
            c[t] += 1
            where.setdefault(t, (fn, i))
for t, n in sorted(c.items(), key=lambda kv: -kv[1]):
    print(n, t, where[t])

